<script setup lang="ts">import {ref,computed} from 'vue';import type {Corpus,Document,User} from '../types/domain';import {corpusApi} from '../api/corpora';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';const props=defineProps<{corpora:Corpus[];documents:Document[];whitelist:string[];user:User;reload:()=>Promise<any>}>();const corpusId=ref(0),show=ref(false),name=ref(''),raw=ref(''),edit=ref<Document|null>(null),title=ref(''),text=ref('');const active=computed(()=>corpusId.value||props.corpora[0]?.id),docs=computed(()=>props.documents.filter(d=>d.corpus_id===active.value));const {task,act}=useAsync();function choose(d:Document){edit.value=d;title.value=d.title;text.value=d.tokens_text}async function submit(){await act(async()=>{await corpusApi.create({name:name.value,filename:name.value+'.json',description:'编辑导入的已分词摘要',documents:JSON.parse(raw.value)});await props.reload();show.value=false},'分词语料已导入')};</script><template><PageTitle index="02 / TOKEN CORPUS" title="词已经分好，口径仍要核对。" description="只按空白切词，精确匹配固定50词白名单；不做中文自动分词。白名单后或min_df后空词文档单独记录，不伪造主题得分。"><button v-if="user.role!=='viewer'" @click="show=!show">导入分词语料 ↗</button></PageTitle><Notice :error="task.error" :message="task.message"/><form class="editor" v-if="show" @submit.prevent="submit"><h2>导入5–1000份JSON文档</h2><label>语料名称<input v-model="name" required maxlength="100"/></label><label>文档JSON数组<textarea rows="6" v-model="raw" required placeholder='[{"reference":"DOC-001","title":"展签摘要","tokens_text":"陶土 材料 工艺"},…]'/></label><button class="primary" :disabled="task.busy">校验并导入</button></form><div class="source-selector"><label>当前语料<select v-model="corpusId"><option :value="0" v-if="corpora[0]">默认 / {{corpora[0].name}}</option><option v-for="c in corpora" :key="c.id" :value="c.id">{{c.name}} / {{c.document_count}}篇</option></select></label><p>{{corpora.find(c=>c.id===active)?.description}}<br/>{{corpora.find(c=>c.id===active)?.filename}}</p></div><div class="whitelist"><small>FIXED WHITELIST / 精确匹配</small><p>{{whitelist.join(' · ')}}</p></div><form v-if="edit" class="editor" @submit.prevent="act(async()=>{await corpusApi.edit(edit!.id,{title,tokens_text:text});await reload();edit=null},'分词文档已修订，历史运行保持原结果')"><h2>修订 {{edit.reference}}</h2><label>标题<input v-model="title" maxlength="120" required/></label><label>已分词文本<textarea rows="4" v-model="text" maxlength="10000"/></label><button class="primary" :disabled="task.busy">保存修订</button></form><div class="section-title"><h2>原始文档样本</h2><small>展示前40 / 总{{docs.length}}，计算用全部</small></div><Table :headers="['文档 / 标题','空白分词摘要','']"><tr v-for="d in docs.slice(0,40)" :key="d.id"><td><small>{{d.reference}}</small><strong>{{d.title}}</strong></td><td class="token-text">{{d.tokens_text||'（空词文档）'}}</td><td><button v-if="user.role!=='viewer'" class="text-button" @click="choose(d)">编辑分词 ↗</button></td></tr></Table></template>
